import {ContractError} from './cloud-contract.mjs';
import {costMonth} from './product-cost-contract.mjs';
import {overviewRecord} from './operating-overview-contract.mjs';
const fail=()=>{throw new ContractError('月结资料不完整，请刷新重新核对。');};
const id=v=>{if(typeof v!=='string'||!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(v))fail();return v;};
const int=(v,min=0)=>{if(!Number.isSafeInteger(v)||v<min||v>2147483647)fail();return v;};
const text=(v,max)=>{if(typeof v!=='string'||!v.trim()||v.length>max)fail();return v.trim();};
const digest=v=>{if(typeof v!=='string'||!/^[a-f0-9]{64}$/.test(v))fail();return v;};
function summary(r){id(r.id);int(r.version,1);if(!['lock','reopen'].includes(r.action)||!Number.isFinite(Date.parse(r.createdAt)))fail();digest(r.sourceHash);text(r.reason,2000);text(r.actor,100);return r;}
function snapshot(s,month){if(!s||s.schemaVersion!==1||s.month!==month||!Array.isArray(s.issues)||!s.counts||!Number.isFinite(Date.parse(s.checkedAt))||!Array.isArray(s.inventory)||!Array.isArray(s.sampleSources)||!Array.isArray(s.expenseIds)||!Array.isArray(s.cash)||!Array.isArray(s.reimbursements)||!Array.isArray(s.sources?.expenses))fail();overviewRecord(s.overview,month);int(s.counts.blocker);int(s.counts.review);return s;}
export function closingRecord(r){summary(r);costMonth(r.month);if(r.previousId!==null)id(r.previousId);if(typeof r.coverageConfirmed!=='boolean'||typeof r.reviewConfirmed!=='boolean'||r.action==='lock'&&(!r.coverageConfirmed||!r.reviewConfirmed))fail();snapshot(r.snapshot,r.month);if(r.snapshot.counts.blocker!==0)fail();return r;}
export function closingState(v,month){if(!v||v.month!==month||!v.history||!Array.isArray(v.history.rows)||v.history.rows.length>50||v.history.limit!==50)fail();int(v.history.total);int(v.history.offset);v.history.rows.forEach(summary);if(v.record!==null){closingRecord(v.record);if(v.record.month!==month)fail();}if(v.record?.action==='lock'){if(v.candidate!==null)fail();}else{if(!v.candidate||typeof v.candidate.ready!=='boolean')fail();digest(v.candidate.sourceHash);snapshot(v.candidate.snapshot,month);if(v.candidate.ready!==(v.candidate.snapshot.counts.blocker===0))fail();}return v;}
export function closingPayload(v){if(!v||Object.keys(v).some(k=>!['requestKey','month','action','expectedVersion','sourceHash','coverageConfirmed','reviewConfirmed','reason'].includes(k))||!['lock','reopen'].includes(v.action)||typeof v.coverageConfirmed!=='boolean'||typeof v.reviewConfirmed!=='boolean'||v.action==='lock'&&(!v.coverageConfirmed||!v.reviewConfirmed)||v.expectedVersion>=2147483647)fail();return {requestKey:id(v.requestKey),month:costMonth(v.month),action:v.action,expectedVersion:int(v.expectedVersion),sourceHash:digest(v.sourceHash),coverageConfirmed:v.coverageConfirmed,reviewConfirmed:v.reviewConfirmed,reason:text(v.reason,2000)};}
export function closingResult(v,month){if(!v||v.month!==month||!['lock','reopen'].includes(v.action))fail();id(v.id);int(v.version,1);return v;}
